(function() {
  window.CardSpoke.Plugin.register('research-hub', {
    manifest: {
      name: 'Research Hub',
      version: '1.0.0',
      author: 'CardSpoke Community',
      description: 'Rebrands CardSpoke as a research-focused tool with a custom menu item for research stats',
      layer: 'app',
      permissions: ['ui-override', 'storage']
    },
    setup: async function(ctx) {
      if (document.getElementById('plugin-research-stats')) return;
      var bar = document.createElement('div');
      bar.id = 'plugin-research-stats';
      document.body.appendChild(bar);
      this._updateStats = function() {
        var cards = ctx.api.data.listCards();
        var totalWords = cards.reduce(function(sum, c) {
          var text = (c.title || '') + ' ' + (c.body || '');
          return sum + text.trim().split(/\s+/).filter(function(w) { return w.length > 0; }).length;
        }, 0);
        var uniqueTags = new Set();
        cards.forEach(function(c) {
          if (c.tags) c.tags.forEach(function(t) { uniqueTags.add(t); });
        });
        var bookmarkCount = cards.filter(function(c) { return c.bookmarked; }).length;
        bar.innerHTML = '<span class="stat-item">Cards: <span class="stat-value">' + cards.length + '</span></span>' +
          '<span class="stat-item">Words: <span class="stat-value">' + totalWords + '</span></span>' +
          '<span class="stat-item">Tags: <span class="stat-value">' + uniqueTags.size + '</span></span>' +
          '<span class="stat-item">Bookmarks: <span class="stat-value">' + bookmarkCount + '</span></span>';
      };
      this._updateStats();
      bar.classList.add('visible');
      if (window.CardSpoke && window.CardSpoke.Middleware) {
        window.CardSpoke.Middleware.register({
          name: 'research-hub-update',
          priority: -100,
          operations: ['card.save', 'card.delete'],
          handler: async function(mwCtx, next) {
            await next();
            if (this._updateStats) this._updateStats();
          }.bind(this)
        });
      }
      ctx.logger.info('Research Hub loaded');
    },
    teardown: async function(ctx) {
      if (window.CardSpoke && window.CardSpoke.Middleware) {
        window.CardSpoke.Middleware.unregister('research-hub-update');
      }
      var bar = document.getElementById('plugin-research-stats');
      if (bar) bar.remove();
      ctx.logger.info('Research Hub disabled');
    }
  });
})();
